mapper.select:
SELECT *
FROM employees


        AND employee_id = #{employeeId}



        AND (
        first_name LIKE CONCAT('%', #{empName}, '%')
        OR last_name LIKE CONCAT('%', #{empName}, '%')
        OR CONCAT(COALESCE(first_name, ''), ' ', COALESCE(last_name, '')) LIKE CONCAT('%', #{empName}, '%')
        OR CONCAT(COALESCE(last_name, ''), COALESCE(first_name, '')) LIKE CONCAT('%', #{empName}, '%')
        )



        AND department_id = #{departmentId}



        AND job_id = #{jobId}



        AND hire_date >= #{hireDate}



        AND salary >= #{minSalary}


ORDER BY employee_id DESC
